#!/bin/sh
# Name: PaperGames
# Author: muyouming
# Icon: data:image/png;base64,
# DontUseFBInk
#
# Offline PaperGames launcher.
# Starts the bundled Lua HTTP server on 127.0.0.1:8080 and opens the stock
# Kindle browser at the game list.

ROOT=/mnt/us/PaperGames
PORT=8080
URL="http://127.0.0.1:$PORT/index.html"
LOG=/var/local/pg-server.log
CURL=/usr/bin/curl
PGREP=/usr/bin/pgrep
SETSID=/usr/bin/setsid
LUAJIT="$ROOT/runtime/luajit"
LIPC=/usr/bin/lipc-set-prop
EIPS=/usr/sbin/eips

if [ ! -f "$ROOT/index.html" ]; then
    "$EIPS" 1 1 "PaperGames files not found"
    sleep 5
    exit 1
fi

# Start the local server if it is not answering yet.
if ! "$CURL" -s -o /dev/null --max-time 2 "$URL"; then
    export LD_LIBRARY_PATH="$ROOT/runtime"
    "$SETSID" "$LUAJIT" "$ROOT/server.lua" "$PORT" >"$LOG" 2>&1 &
    sleep 2
fi

# Open the stock browser if needed, then navigate to the local page.
if ! "$PGREP" -f "chromium/kindle_browser" >/dev/null 2>&1; then
    "$LIPC" com.lab126.appmgrd start app://com.lab126.browser >/dev/null 2>&1
    sleep 8
fi

"$LIPC" -s com.lab126.browser loadURL "$URL"
